SELECT ?person ?st ?pq ?v ?vLabel_en WHERE {
  VALUES ?person { wd:Q52947 wd:Q52945 wd:Q52944 wd:Q52940 wd:Q52939 wd:Q52938 wd:Q52937 wd:Q52936 wd:Q52935 wd:Q52934 wd:Q52933 wd:Q52932 wd:Q52931 wd:Q52930 wd:Q52929 wd:Q52928 wd:Q52927 wd:Q52926 wd:Q52925 wd:Q52924 wd:Q52890 wd:Q52878 wd:Q45068 }
  ?person p:P39 ?st .
  ?st ps:P39 ?pos .
  FILTER(?pos IN (wd:Q1268572, wd:Q3273712))
  ?st ?pq ?v .
  FILTER(STRSTARTS(STR(?pq), "http://www.wikidata.org/prop/qualifier/P") || ?pq = ps:P39)
  OPTIONAL { ?v rdfs:label ?vLabel_en FILTER(LANG(?vLabel_en) = "en") }
}
ORDER BY ?person ?st ?pq

