SELECT ?person ?p ?v ?vLabel ?q ?qv WHERE {
  VALUES ?person { wd:Q52933 wd:Q52945 wd:Q52937 wd:Q52935 wd:Q52928 wd:Q52890 wd:Q52924 wd:Q52947 wd:Q52939 wd:Q201625 wd:Q52929 }
  VALUES ?p { p:P793 p:P1196 p:P20 p:P39 p:P112 p:P1038 }
  ?person ?p ?st .
  ?st ?ps ?v .
  FILTER(STRSTARTS(STR(?ps), "http://www.wikidata.org/prop/statement/P"))
  OPTIONAL { ?st ?q ?qv . FILTER(STRSTARTS(STR(?q), "http://www.wikidata.org/prop/qualifier/P")) }
  OPTIONAL { ?v rdfs:label ?vLabel FILTER(LANG(?vLabel) = "en") }
}

